/** One of BookingPromoClientDTO, BookingPromoDriverDTO, chosen by `view`. */
@Serializable(with = BookingPromo.Serializer::class)
sealed interface BookingPromo {
    object Serializer : JsonContentPolymorphicSerializer<BookingPromo>(BookingPromo::class) {
        override fun selectDeserializer(element: JsonElement) =
            when (val tag = element.jsonObject["view"]?.jsonPrimitive?.content) {
                "client" -> BookingPromoClientDTO.serializer()
                "driver" -> BookingPromoDriverDTO.serializer()
                else -> throw IllegalArgumentException("BookingPromo: unknown view '$tag'")
            }
    }
}

